          next: "继续沿崖壁向前，看到整面金色手臂组成的龛窟就是千手观音。",
          script: "这三尊立像高约七米，中间毗卢遮那佛，两边文殊、普贤。请盯住文殊菩萨的手：他托着一座七级宝塔，塔重近千斤，八百年没有掉下来。秘密在袈裟上——工匠让袈裟从手臂一直垂到脚边，等于给石塔加了一根斜撑，把重量引回身体。宋代工匠不懂结构力学的公式，但他们懂石头。这就是大足给我的第一个震撼：信仰的题目，最后是用工程智慧解出来的。",
