    "莫角山宫殿区为人工堆筑台地，面积约30万平方米、高出周边十余米，上有三座宫殿台顶，是全城的权力核心区。",
    "反山王陵1986年发掘，清理11座良渚文化大墓，出土随葬品1200余件（组），是良渚文化等级最高的墓地。",
