    "钱塘江大桥1937年9月26日通车，是中国人自行设计建造的第一座双层铁路公路两用桥，2006年列为全国重点文物保护单位。",
    "钱塘江大桥全长1453米，上层公路下层铁路，1937年12月为阻日军曾自行炸毁，1948年修复通车，至今仍在使用。",
