  routeSourceNotes["hangzhou-lingyin"] = "资料参考：灵隐寺景区官方介绍、飞来峰造像全国重点文物保护单位档案、杭州西湖风景名胜区管委会宋韵迹忆专题、新华社及人民日报相关报道。";
  routeSourceNotes["hangzhou-hefang"] = "资料参考：杭州市文化广电旅游局文保档案、上城区志与上城年鉴、新华社及人民日报对南宋御街保护工程的报道、胡庆余堂与胡雪岩故居官方展陈说明。";
  routeSourceNotes["hangzhou-liangzhu"] = "资料参考：联合国教科文组织世界遗产名录良渚古城遗址条目、国家文物局与浙江省文物考古研究所发掘报告、新华社与人民日报申遗报道、良渚古城遗址公园官方导览。";
  routeSourceNotes["hangzhou-qiantang"] = "资料参考：杭州市文化广电旅游局六和塔与闸口白塔文保档案、浙江宣传《六和千年》、钱塘江大桥纪念馆资料、新华社及人民日报相关报道。";

  // 现有路线增强：西湖北线文人线
  const westlake = city.routes.find((r) => r.id === "hangzhou-westlake");
