    "空海804年随遣唐使入唐，在青龙寺拜密宗七祖惠果为师，受金刚界、胎藏界两部灌顶，806年回国后在和歌山高野山创立日本真言宗。",
    "青龙寺前身是隋开皇二年（582年）创建的灵感寺，唐景云二年（711年）改名青龙寺，845年会昌灭佛时被废，明代以后地面建筑无存。",
    "1973年至1980年中国社会科学院考古研究所对青龙寺遗址进行发掘，确认了寺院范围和殿堂基址；20世纪80年代中日共建空海纪念碑与惠果空海纪念堂。",
    "史料记载入唐八家之中有六位日本僧人都曾在青龙寺受法，这里因此兼有汉传密宗祖庭与日本真言宗发源地的双重身份。"
