    "白塔是台怀镇最强的视觉中心。它不需要复杂解释，因为它直接改变了整个山谷的视线组织。你无论从哪个方向走来，都会被它重新定位。对旅行者来说，地标的意义正在这里：它让陌生空间突然有了方向。这座大白塔通高56.4米，覆钵式造型，相传由尼泊尔匠师阿尼哥设计、明万历年间重修，塔下供有释迦牟尼舍利——五台山的标志从来不是某座山，而是它。",
